script:
if doc.get("product_delivery"):
    frappe.db.set_value("Product Delivery", doc.product_delivery, {
        "transfer_status": "Transferred",
        "stock_entry": doc.name
    })

if doc.get("product_delivery"):
    frappe.db.set_value("Product Delivery", doc.product_delivery, {
        "transfer_status": "Pending",
        "stock_entry": None
    })

if doc.get("installation"):
    if doc.purpose == "Material Issue":
        frappe.db.set_value("Installation", doc.installation, {
            "consumption_stock_entry": doc.name,
            "material_status": "Consumption Posted"
        })
    elif doc.purpose == "Material Transfer":
        frappe.db.set_value("Installation", doc.installation, {
            "return_stock_entry": doc.name,
            "material_status": "Closed"
        })

if doc.get("installation"):
    if doc.purpose == "Material Issue":
        frappe.db.set_value("Installation", doc.installation, {
            "consumption_stock_entry": None,
            "material_status": "Pending"
        })
    elif doc.purpose == "Material Transfer":
        frappe.db.set_value("Installation", doc.installation, {
            "return_stock_entry": None,
            "material_status": "Consumption Posted"
        })

rows = doc.get("commissioning_checklist") or []

required = [r for r in rows if r.is_required]
pending = [r for r in required if r.status not in ("OK", "Not Applicable")]
failed = [r for r in rows if r.status == "Not OK"]
cleared = len(required) - len(pending)

summary = str(cleared) + " of " + str(len(required)) + " required checks cleared"
if failed:
    summary = summary + "  •  " + str(len(failed)) + " marked Not OK"
doc.checks_summary = summary

if doc.status_of_project_commission == "Commissioned":
    problems = []

    if not rows:
        problems.append("The commissioning checklist is empty.")

    if pending:
        names = ", ".join([r.check_item for r in pending[:5]])
        extra = " and " + str(len(pending) - 5) + " more" if len(pending) > 5 else ""
        problems.append("These required checks are not cleared: " + names + extra)

    if failed:
        names = ", ".join([r.check_item for r in failed[:5]])
        problems.append("These checks are marked Not OK: " + names)

    if not doc.commissioning_certificate:
        problems.append("Commissioning Certificate is not attached.")

    if not doc.final_handover_document:
        problems.append("Final Handover Document is not attached.")

    if not doc.customer_acceptance:
        problems.append("Customer Acceptance has not been ticked.")

    if problems:
        frappe.throw("Cannot mark this project as Commissioned yet:<br><br>• " + "<br>• ".join(problems))

# Stamps the consumed date, derives the warranty and AMC expiry dates from
# their period and unit, and sets both statuses. Runs server side so it also
# applies when a stock transaction changes the serial rather than a user
# editing the form.

# Once set, the consumed date is never cleared - the warranty start must
# survive any later status change.
if doc.status == "Consumed" and not doc.custom_consumed_date:
    doc.custom_consumed_date = frappe.utils.nowdate()

today = frappe.utils.getdate(frappe.utils.nowdate())

# ---- warranty ----
w_start = doc.custom_consumed_date
w_qty = frappe.utils.cint(doc.custom_warranty_period)
w_unit = doc.custom_warranty_period_unit or "Years"

if w_start and w_qty > 0:
    d = frappe.utils.getdate(w_start)
    if w_unit == "Days":
        doc.warranty_expiry_date = frappe.utils.add_days(d, w_qty)
    elif w_unit == "Months":
        doc.warranty_expiry_date = frappe.utils.add_months(d, w_qty)
    else:
        doc.warranty_expiry_date = frappe.utils.add_months(d, w_qty * 12)
elif not w_start:
    doc.warranty_expiry_date = None

if not w_start or not doc.warranty_expiry_date:
    doc.custom_warranty_status = "Not Started"
elif frappe.utils.getdate(doc.warranty_expiry_date) >= today:
    doc.custom_warranty_status = "Ongoing"
else:
    doc.custom_warranty_status = "Expired"

# ---- amc ----
# AMC start is entered by hand, since it usually begins when the warranty ends
# rather than on the consumed date.
a_start = doc.custom_amc_start_date
a_qty = frappe.utils.cint(doc.custom_amc_period)
a_unit = doc.custom_amc_period_unit or "Years"

if a_start and a_qty > 0:
    d = frappe.utils.getdate(a_start)
    if a_unit == "Days":
        doc.amc_expiry_date = frappe.utils.add_days(d, a_qty)
    elif a_unit == "Months":
        doc.amc_expiry_date = frappe.utils.add_months(d, a_qty)
    else:
        doc.amc_expiry_date = frappe.utils.add_months(d, a_qty * 12)
elif not a_start:
    doc.amc_expiry_date = None

if not a_start or not doc.amc_expiry_date:
    doc.custom_amc_status = "Not Started"
elif frappe.utils.getdate(doc.amc_expiry_date) >= today:
    doc.custom_amc_status = "Ongoing"
else:
    doc.custom_amc_status = "Expired"

# Keep ERPNext's own Maintenance Status consistent with the two above.
if doc.custom_amc_status == "Ongoing":
    doc.maintenance_status = "Under AMC"
elif doc.custom_warranty_status == "Ongoing":
    doc.maintenance_status = "Under Warranty"
elif doc.custom_amc_status == "Expired":
    doc.maintenance_status = "Out of AMC"
elif doc.custom_warranty_status == "Expired":
    doc.maintenance_status = "Out of Warranty"
